var cfg = $('Set Exporter Config').first().json;
var store = $getWorkflowStaticData('global');
var nowMs = Date.now();

var cachedBody = typeof store.body === 'string' ? store.body : '';
var cachedMeta = (store.meta && typeof store.meta === 'object') ? store.meta : null;
var cachedAt = typeof store.cached_at === 'number' ? store.cached_at : 0;
var lastSuccess = typeof store.last_success === 'number' ? store.last_success : 0;

var ttl = Number(cfg.cache_ttl_seconds);
if (!isFinite(ttl) || ttl < 0) ttl = 30;

var ageSeconds = cachedAt > 0 ? (nowMs - cachedAt) / 1000 : -1;
var cacheFresh = (cachedBody !== '' && ageSeconds >= 0 && ageSeconds < ttl);

return [{ json: {
  started_at: nowMs,
  cache_fresh: cacheFresh,
  cache_age_seconds: ageSeconds < 0 ? 0 : ageSeconds,
  cached_body: cachedBody,
  cached_meta: cachedMeta,
  last_success: lastSuccess,
  degraded: false,
  cache_hit: cacheFresh,
  body: cacheFresh ? cachedBody : '',
  meta: cacheFresh ? cachedMeta : null
} }];

var cfg = $('Set Exporter Config').first().json;
var items = $input.all();

var prefix = String(cfg.exporter_prefix == null ? '' : cfg.exporter_prefix).trim();
if (prefix === '') prefix = 'sheet_exporter';

var maxSeries = Number(cfg.max_series);
if (!isFinite(maxSeries) || maxSeries < 1) maxSeries = 2000;

var NL = String.fromCharCode(10);
var CR = String.fromCharCode(13);
var BS = String.fromCharCode(92);
var SEP = String.fromCharCode(0);

var nameRe = new RegExp('^[a-zA-Z_:][a-zA-Z0-9_:]*$');
var labelRe = new RegExp('^[a-zA-Z_][a-zA-Z0-9_]*$');
var allowedTypes = ['gauge', 'counter', 'untyped'];
var reservedNames = ['up', 'scrape_duration_seconds', 'scrape_samples_scraped', 'scrape_samples_post_metric_relabeling', 'scrape_series_added', 'scrape_body_size_bytes', 'scrape_timeout_seconds'];

var skipped = { bad_label_name: 0, bad_labels: 0, bad_name: 0, bad_type: 0, bad_value: 0, blank_value: 0, duplicate: 0, over_cap: 0, reserved_name: 0 };
var warnings = { scrape_label: 0, type_conflict: 0 };
var notes = [];

function clean(v){
  var s = String(v == null ? '' : v);
  var out = '';
  for (var i = 0; i < s.length; i++){
    var ch = s.charAt(i);
    if (ch === NL || ch === CR) out += ' ';
    else out += ch;
  }
  if (out.length > 60) out = out.slice(0, 60);
  return out;
}

function note(text){
  if (notes.length < 20) notes.push(text);
}

function parseValue(raw){
  var t = String(raw == null ? '' : raw).trim();
  if (t === '') return { ok: false, reason: 'blank_value' };
  var low = t.toLowerCase();
  if (low === 'nan') return { ok: true, text: 'NaN' };
  if (low === 'inf' || low === '+inf' || low === 'infinity' || low === '+infinity') return { ok: true, text: '+Inf' };
  if (low === '-inf' || low === '-infinity') return { ok: true, text: '-Inf' };
  var n = Number(t);
  if (typeof raw !== 'boolean' && isFinite(n)) return { ok: true, text: String(n) };
  return { ok: false, reason: 'bad_value' };
}

function parseLabels(raw){
  var s = String(raw == null ? '' : raw).trim();
  var pairs = [];
  if (s === '') return { ok: true, labels: pairs };
  var i = 0;
  var n = s.length;
  while (i < n){
    while (i < n && s.charAt(i) === ' ') i++;
    var key = '';
    while (i < n && s.charAt(i) !== '=' && s.charAt(i) !== ',') { key += s.charAt(i); i++; }
    key = key.trim();
    if (i >= n || s.charAt(i) !== '=') return { ok: false, reason: 'bad_labels' };
    i++;
    var val = '';
    if (i < n && s.charAt(i) === '"'){
      i++;
      var closed = false;
      while (i < n){
        var c = s.charAt(i);
        if (c === BS && i + 1 < n){
          var nx = s.charAt(i + 1);
          if (nx === BS){ val += BS; i += 2; }
          else if (nx === '"'){ val += '"'; i += 2; }
          else if (nx === 'n'){ val += NL; i += 2; }
          else { val += c; i++; }
        }
        else if (c === '"'){ i++; closed = true; break; }
        else { val += c; i++; }
      }
      if (!closed) return { ok: false, reason: 'bad_labels' };
      while (i < n && s.charAt(i) === ' ') i++;
      if (i < n && s.charAt(i) !== ',') return { ok: false, reason: 'bad_labels' };
      if (i < n) i++;
    } else {
      while (i < n && s.charAt(i) !== ',') { val += s.charAt(i); i++; }
      if (i < n) i++;
      val = val.trim();
      if (val.length > 1 && val.charAt(0) === '"' && val.charAt(val.length - 1) === '"'){
        val = val.slice(1, val.length - 1);
      }
    }
    if (key === '') return { ok: false, reason: 'bad_labels' };
    if (key.indexOf('__') === 0) return { ok: false, reason: 'bad_label_name' };
    if (!labelRe.test(key)) return { ok: false, reason: 'bad_label_name' };
    if (val !== '') pairs.push([key, val]);
  }
  pairs.sort(function(a, b){ return a[0] < b[0] ? -1 : (a[0] > b[0] ? 1 : 0); });
  for (var d = 1; d < pairs.length; d++){
    if (pairs[d][0] === pairs[d - 1][0]) return { ok: false, reason: 'bad_labels' };
  }
  return { ok: true, labels: pairs };
}

var families = {};
var seen = {};
var series = [];
var rowsIn = 0;

for (var r = 0; r < items.length; r++){
  var row = items[r].json;
  var rowNum = (row.row_number != null && isFinite(Number(row.row_number))) ? Number(row.row_number) : (r + 2);
  var name = String(row.metric_name == null ? '' : row.metric_name).trim();
  if (name === '') continue;
  rowsIn++;

  if (!nameRe.test(name)){
    skipped.bad_name++;
    note('skipped row ' + rowNum + ': bad_name ' + clean(name));
    continue;
  }
  if (reservedNames.indexOf(name) >= 0 || name === prefix || name.indexOf(prefix + '_') === 0){
    skipped.reserved_name++;
    note('skipped row ' + rowNum + ': reserved_name ' + clean(name));
    continue;
  }

  var typeRaw = String(row.type == null ? '' : row.type).trim().toLowerCase();
  if (typeRaw !== '' && allowedTypes.indexOf(typeRaw) < 0){
    skipped.bad_type++;
    note('skipped row ' + rowNum + ': bad_type ' + clean(typeRaw));
    continue;
  }

  var lab = parseLabels(row.labels);
  if (!lab.ok){
    skipped[lab.reason]++;
    note('skipped row ' + rowNum + ': ' + lab.reason + ' ' + clean(row.labels));
    continue;
  }

  var val = parseValue(row.value);
  if (!val.ok){
    skipped[val.reason]++;
    note('skipped row ' + rowNum + ': ' + val.reason + ' ' + clean(row.value));
    continue;
  }

  for (var w = 0; w < lab.labels.length; w++){
    var lk = lab.labels[w][0];
    if (lk === 'job' || lk === 'instance'){
      warnings.scrape_label++;
      note('warning row ' + rowNum + ': label ' + lk + ' is renamed to exported_' + lk + ' by Prometheus');
    }
  }

  var fkey = 'm:' + name;
  if (!Object.prototype.hasOwnProperty.call(families, fkey)) families[fkey] = { help: '', type: '' };
  var fam = families[fkey];
  var help = String(row.help == null ? '' : row.help).trim();
  if (fam.help === '' && help !== '') fam.help = help;
  if (typeRaw !== ''){
    if (fam.type === '') fam.type = typeRaw;
    else if (fam.type !== typeRaw){
      warnings.type_conflict++;
      note('warning row ' + rowNum + ': type ' + typeRaw + ' conflicts with ' + fam.type);
    }
  }

  var parts = [];
  for (var q = 0; q < lab.labels.length; q++) parts.push(lab.labels[q][0] + '=' + lab.labels[q][1]);
  var skey = 's:' + name + SEP + parts.join(',');
  var entry = { name: name, labels: lab.labels, value: val.text, row: rowNum };

  if (Object.prototype.hasOwnProperty.call(seen, skey)){
    skipped.duplicate++;
    note('skipped row ' + series[seen[skey]].row + ': duplicate series, row ' + rowNum + ' wins');
    series[seen[skey]] = entry;
  } else {
    seen[skey] = series.length;
    series.push(entry);
  }
}

series.sort(function(a, b){
  if (a.name !== b.name) return a.name < b.name ? -1 : 1;
  var ka = '';
  var kb = '';
  var x;
  for (x = 0; x < a.labels.length; x++) ka += a.labels[x][0] + '=' + a.labels[x][1] + ',';
  for (x = 0; x < b.labels.length; x++) kb += b.labels[x][0] + '=' + b.labels[x][1] + ',';
  return ka < kb ? -1 : (ka > kb ? 1 : 0);
});

if (series.length > maxSeries){
  skipped.over_cap += (series.length - maxSeries);
  series = series.slice(0, maxSeries);
  note('skipped: series cap ' + maxSeries + ' reached, extra series dropped');
}

return [{ json: {
  series: series,
  families: families,
  meta: {
    rows_in: rowsIn,
    rows_kept: series.length,
    series_count: series.length,
    skipped: skipped,
    warnings: warnings,
    notes: notes
  }
} }];

var input = $input.first().json;
var series = input.series || [];
var families = input.families || {};
var meta = input.meta || {};

var NL = String.fromCharCode(10);
var CR = String.fromCharCode(13);
var BS = String.fromCharCode(92);

function escLabel(v){
  var s = String(v);
  var out = '';
  for (var i = 0; i < s.length; i++){
    var ch = s.charAt(i);
    if (ch === BS) out += BS + BS;
    else if (ch === '"') out += BS + '"';
    else if (ch === NL) out += BS + 'n';
    else if (ch === CR) out += '';
    else out += ch;
  }
  return out;
}

function escHelp(v){
  var s = String(v);
  var out = '';
  for (var i = 0; i < s.length; i++){
    var ch = s.charAt(i);
    if (ch === BS) out += BS + BS;
    else if (ch === NL) out += BS + 'n';
    else if (ch === CR) out += '';
    else out += ch;
  }
  return out;
}

var out = [];
var i;
var skippedTotal = 0;
var sk = meta.skipped || {};
for (var key in sk){
  if (Object.prototype.hasOwnProperty.call(sk, key)) skippedTotal += Number(sk[key]) || 0;
}

out.push('# sheet exporter read ' + (Number(meta.rows_in) || 0) + ' rows, exported ' + series.length + ' series, skipped ' + skippedTotal);

var notes = meta.notes || [];
for (i = 0; i < notes.length; i++) out.push('# ' + notes[i]);

var order = [];
var groups = {};
for (i = 0; i < series.length; i++){
  var gk = 'm:' + series[i].name;
  if (!Object.prototype.hasOwnProperty.call(groups, gk)){
    groups[gk] = [];
    order.push(series[i].name);
  }
  groups[gk].push(series[i]);
}
order.sort();

for (i = 0; i < order.length; i++){
  var name = order[i];
  var fam = Object.prototype.hasOwnProperty.call(families, 'm:' + name) ? families['m:' + name] : { help: '', type: '' };
  if (fam.help) out.push('# HELP ' + name + ' ' + escHelp(fam.help));
  out.push('# TYPE ' + name + ' ' + (fam.type ? fam.type : 'gauge'));
  var list = groups['m:' + name];
  for (var j = 0; j < list.length; j++){
    var labels = list[j].labels;
    var lbl = '';
    if (labels.length){
      var parts = [];
      for (var k = 0; k < labels.length; k++){
        parts.push(labels[k][0] + '="' + escLabel(labels[k][1]) + '"');
      }
      lbl = '{' + parts.join(',') + '}';
    }
    out.push(name + lbl + ' ' + list[j].value);
  }
}

var body = out.length ? (out.join(NL) + NL) : '';

return [{ json: { body: body, meta: meta, degraded: false, cache_hit: false } }];

var input = $input.first().json;
var store = $getWorkflowStaticData('global');

var MAX_BODY_BYTES = 200000;
var body = String(input.body == null ? '' : input.body);
var meta = input.meta || {};
var nowMs = Date.now();
var nowSec = Math.floor(nowMs / 1000);

if (body.length <= MAX_BODY_BYTES){
  store.body = body;
  store.meta = meta;
  store.cached_at = nowMs;
} else {
  store.body = '';
  store.meta = null;
  store.cached_at = 0;
}
store.last_success = nowSec;

return [{ json: {
  body: body,
  meta: meta,
  degraded: false,
  cache_hit: false,
  last_success: nowSec
} }];

var cfg = $('Set Exporter Config').first().json;
var ctx = $('Read Metrics Cache').first().json;
var input = $input.first().json;

var NL = String.fromCharCode(10);
var CR = String.fromCharCode(13);

var prefix = String(cfg.exporter_prefix == null ? '' : cfg.exporter_prefix).trim();
if (prefix === '') prefix = 'sheet_exporter';

var serveStale = (cfg.serve_stale_on_error === true || String(cfg.serve_stale_on_error) === 'true');

var failCode = Number(cfg.fail_status_code);
if (!isFinite(failCode) || failCode < 200 || failCode > 599) failCode = 200;

var degraded = (input.degraded === true);

var startedAt = Number(ctx.started_at);
if (!isFinite(startedAt) || startedAt <= 0) startedAt = Date.now();
var durationSeconds = (Date.now() - startedAt) / 1000;

var body = '';
var meta = null;
var cacheHit = false;
var cacheAge = 0;
var errorText = '';

if (degraded){
  errorText = String(input.error_message == null ? 'sheet read failed' : input.error_message);
  var scrubbed = '';
  for (var e = 0; e < errorText.length; e++){
    var ec = errorText.charAt(e);
    scrubbed += (ec === NL || ec === CR) ? ' ' : ec;
  }
  errorText = scrubbed.length > 120 ? scrubbed.slice(0, 120) : scrubbed;
  if (serveStale && input.cached_body){
    body = String(input.cached_body);
    meta = input.cached_meta || null;
    cacheAge = Number(ctx.cache_age_seconds) || 0;
  }
} else {
  body = String(input.body == null ? '' : input.body);
  meta = input.meta || null;
  cacheHit = (input.cache_hit === true);
  cacheAge = cacheHit ? (Number(ctx.cache_age_seconds) || 0) : 0;
}

var lastSuccess = Number(input.last_success);
if (!isFinite(lastSuccess) || lastSuccess <= 0) lastSuccess = Number(ctx.last_success) || 0;

var skipped = (meta && meta.skipped) ? meta.skipped : {};
var warnings = (meta && meta.warnings) ? meta.warnings : {};
var seriesCount = (meta && isFinite(Number(meta.series_count))) ? Number(meta.series_count) : 0;
var rowsRead = (meta && isFinite(Number(meta.rows_in))) ? Number(meta.rows_in) : 0;

var REASONS = ['bad_label_name', 'bad_labels', 'bad_name', 'bad_type', 'bad_value', 'blank_value', 'duplicate', 'over_cap', 'reserved_name'];
var RULES = ['scrape_label', 'type_conflict'];

var lines = [];
function family(name, help, samples){
  lines.push('# HELP ' + name + ' ' + help);
  lines.push('# TYPE ' + name + ' gauge');
  for (var i = 0; i < samples.length; i++) lines.push(samples[i]);
}
function num(v){
  var n = Number(v);
  return isFinite(n) ? String(n) : '0';
}

if (degraded) lines.push('# sheet read failed: ' + errorText);

family(prefix + '_up', '1 if the last sheet read succeeded, 0 if it failed', [prefix + '_up ' + (degraded ? '0' : '1')]);
family(prefix + '_series', 'Number of series exported from the sheet in this response', [prefix + '_series ' + num(seriesCount)]);
family(prefix + '_rows_read', 'Number of sheet rows with a metric name in this response', [prefix + '_rows_read ' + num(rowsRead)]);

var skipSamples = [];
for (var s = 0; s < REASONS.length; s++){
  skipSamples.push(prefix + '_rows_skipped{reason="' + REASONS[s] + '"} ' + num(skipped[REASONS[s]] || 0));
}
family(prefix + '_rows_skipped', 'Sheet rows rejected by validation, by reason', skipSamples);

var warnSamples = [];
for (var w = 0; w < RULES.length; w++){
  warnSamples.push(prefix + '_warnings{rule="' + RULES[w] + '"} ' + num(warnings[RULES[w]] || 0));
}
family(prefix + '_warnings', 'Non-fatal sheet problems, by rule', warnSamples);

family(prefix + '_last_success_timestamp_seconds', 'Unix time of the last successful sheet read', [prefix + '_last_success_timestamp_seconds ' + num(lastSuccess)]);
family(prefix + '_scrape_duration_seconds', 'Time spent building this response', [prefix + '_scrape_duration_seconds ' + num(durationSeconds)]);
family(prefix + '_cache_age_seconds', 'Age of the cached body served, 0 on a fresh read', [prefix + '_cache_age_seconds ' + num(cacheAge)]);
family(prefix + '_cache_hit', '1 if this response was served from cache', [prefix + '_cache_hit ' + (cacheHit ? '1' : '0')]);

var head = '';
if (body !== ''){
  head = (body.charAt(body.length - 1) === NL) ? body : (body + NL);
}
var finalBody = head + lines.join(NL) + NL;

return [{ json: { body: finalBody, http_status: (degraded ? failCode : 200) } }];
